type Data = Record<string, unknown>;
type Editor = { title:string; op:string; data:Data; revision:number; key:string; baseline?:string };
type Page = '今天'|'习惯'|'六维'|'收集'|'复盘'|'设置';
const tabs:Page[]=['今天','习惯','六维','收集','复盘'];
const draftKey='six-workspace-drafts-v1';
// Mobile scrolls the content pane so the navigation stays outside the scroll area.
const workspaceScroller=()=>window.matchMedia('(max-width:760px)').matches?document.querySelector<HTMLElement>('.ws-content'):null;
const workspaceScrollTop=()=>workspaceScroller()?.scrollTop??window.scrollY;
const scrollWorkspaceTo=(top:number)=>(workspaceScroller()??window).scrollTo({top,behavior:'instant'});
const isOpen=(t:Task)=>!['完成','取消','跳过','未记录'].includes(t.status);
const taskStatusLabel=(t:Task)=>t.status==='未开始'&&!t.is_habit?(t.date?'待执行':'待安排'):t.status;
const markedFirst=(t:Task)=>Boolean(t.first_do_date&&t.first_do_date===t.date&&t.first_do_date>=todayKey());
const scheduled=(t:Task)=>!t.is_habit&&(t.source==='calendar'||!!t.due_time);
const canDeferWaiting=(t:Task)=>t.status==='等待反馈'&&!t.is_habit&&(!waitingDeadline(t)||waitingDeadline(t)!<=todayKey());
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const text=(d:Data,k:string)=>String(d[k]??'');
const createdLabel=(value:string)=>{const date=new Date(value);return Number.isNaN(date.getTime())?'时间未记录':date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});};
const shortCreatedLabel=(value:string)=>{const date=new Date(value);return Number.isNaN(date.getTime())?'时间未记录':date.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});};
const byCreatedAt=<T extends {created_at:string;id:string}>(a:T,b:T)=>a.created_at.localeCompare(b.created_at)||a.id.localeCompare(b.id);
function readDrafts():Record<string,Editor>{try{return JSON.parse(localStorage.getItem(draftKey)||'{}');}catch{return {};}}
function ReviewDisclosure({className,initialOpen=false,open:controlledOpen,onOpenChange,reviewKey,children}:{className:string;initialOpen?:boolean;open?:boolean;onOpenChange?:(open:boolean)=>void;reviewKey?:string;children:ReactNode}){
  const [localOpen,setLocalOpen]=useState(initialOpen),open=controlledOpen??localOpen;
  return <details className={className} data-review-project={reviewKey} open={open} onToggle={event=>{const next=event.currentTarget.open;if(next===open)return;if(onOpenChange)onOpenChange(next);else setLocalOpen(next);}}>{children}</details>;
}
function ReviewEntryOrder({groups,children}:{groups:ProjectReviewGroup[];children:(ordered:ProjectReviewGroup[])=>ReactNode}){
  const [entryKeys,setEntryKeys]=useState(()=>groups.map(group=>group.key));
  useEffect(()=>{
    setEntryKeys(previous=>{const known=new Set(previous),added=groups.filter(group=>!known.has(group.key)).map(group=>group.key);return added.length?[...previous,...added]:previous;});
  },[groups]);
  return children(preserveReviewOrder(groups,entryKeys));
}

