  function habitCards(items:Habit[]){return items.length?<div className="ws-cards">{items.map(h=>{const bounds=dateBounds('week');const logs=state!.tasks.filter(t=>t.habit_id===h.id);const count=logs.filter(t=>t.status==='完成'&&t.date>=bounds.start&&t.date<=bounds.end).length;return <details className="ws-compact" key={h.id}><summary><span>{h.title}</span><small>{meta(h)} · {h.frequency} · 本周 {count} 次</small><span className={`ws-badge ws-habit-status ${h.active?'ws-habit-active':'ws-habit-paused'}`}>{h.active?'已启用':'已暂停'}</span></summary><div className="ws-compact-body"><div className="ws-actions"><button onClick={()=>setHabitCalendarId(h.id)}>打卡日历</button><button onClick={()=>editEntity('习惯',h)}>编辑频次</button><button disabled={busy} onClick={()=>void command('habit_active',{id:h.id,active:!h.active})}>{h.active?'暂停习惯':'恢复习惯'}</button><button disabled={busy} onClick={()=>setDeletingHabit(h)}>删除</button></div></div></details>;})}</div>:<p className="ws-empty">还没有习惯。可以按每天、指定星期或每周自由三次设置。</p>;}
